*/
#leftPluginSidebar.plugin-sidebar {
  width: var(--left-sidebar-width, 320px);
  flex: 0 0 var(--left-sidebar-width, 320px);
  min-width: 0;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  z-index: 41;
  background: var(--gtp-panel-bg);
