.plugin-widget-status { font-size: var(--gtp-type-fine); font-weight: var(--gtp-weight-meta); color: var(--gtp-faint); white-space: nowrap; }
@media (max-width: 1023px) {
  #leftMarketSidebar.market-sidebar,
